public static void main(String[] args) {
    MyScanner sc = new MyScanner();
    PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

    int n = sc.nextInt();
    long k = sc.nextInt();
    HashSet<Long> set = new HashSet<>();
    for (int i = 0; i < n; i++) {
        long data = sc.nextLong();
        set.add(data);
    }
    long sum1 = 0;
    for (long i = 1; i <= k; i++) {
        if (!set.contains(i)) {
            sum1 += i;
        }
    }
    out.println(sum1);
    out.close();
}
